<?php require_once '../includes/auth.php'; require_role('supplier'); $page_title='Purchase Flow'; $uid=(int)$_SESSION['user_id'];
if(isset($_POST['purchase'])){ $pid=(int)$_POST['product_id']; $wid=(int)$_POST['warehouse_id']; $qty=(int)$_POST['qty']; $rate=(float)$_POST['rate']; $gst=(float)$_POST['gst']; $gsttotal=$qty*$rate*$gst/100; $total=$qty*$rate; $grand=$total+$gsttotal; $no='PUR'.time(); mysqli_query($conn,"INSERT INTO purchases(supplier_user_id,purchase_no,total,gst_total,grand_total,created_by) VALUES($uid,'$no',$total,$gsttotal,$grand,$uid)"); $pur=mysqli_insert_id($conn); mysqli_query($conn,"INSERT INTO purchase_items(purchase_id,product_id,qty,rate,gst_percent,line_total) VALUES($pur,$pid,$qty,$rate,$gst,$grand)"); mysqli_query($conn,"INSERT INTO stock(product_id,warehouse_id,owner_id,owner_role,quantity,reorder_level) VALUES($pid,$wid,$uid,'supplier',$qty,5) ON DUPLICATE KEY UPDATE quantity=quantity+$qty"); log_audit($conn,$uid,'Purchase Stock',"Purchase $no"); redirect('purchases.php'); }
include '../includes/header.php'; include '../includes/sidebar.php'; $products=mysqli_query($conn,"SELECT * FROM products WHERE supplier_id=$uid"); $wh=mysqli_query($conn,"SELECT * FROM warehouses WHERE owner_id=$uid"); $purchases=mysqli_query($conn,"SELECT * FROM purchases WHERE supplier_user_id=$uid ORDER BY id DESC"); ?>
<div class="row g-4"><div class="col-md-4"><div class="card-box"><h5>New Purchase</h5><form method="POST"><select class="form-select mb-2" name="product_id"><?php while($p=mysqli_fetch_assoc($products)){ ?><option value="<?php echo $p['id']; ?>"><?php echo $p['name']; ?></option><?php } ?></select><select class="form-select mb-2" name="warehouse_id"><?php while($w=mysqli_fetch_assoc($wh)){ ?><option value="<?php echo $w['id']; ?>"><?php echo $w['name']; ?></option><?php } ?></select><input class="form-control mb-2" name="qty" type="number" placeholder="Qty"><input class="form-control mb-2" name="rate" type="number" step="0.01" placeholder="Rate"><input class="form-control mb-3" name="gst" type="number" step="0.01" value="18"><button name="purchase" class="btn btn-success">Add Purchase</button></form></div></div><div class="col-md-8"><div class="card-box"><h5>Purchase History</h5><table class="table"><tr><th>No</th><th>Total</th><th>GST</th><th>Grand</th><th>Date</th></tr><?php while($r=mysqli_fetch_assoc($purchases)){ ?><tr><td><?php echo $r['purchase_no']; ?></td><td><?php echo money($r['total']); ?></td><td><?php echo money($r['gst_total']); ?></td><td><?php echo money($r['grand_total']); ?></td><td><?php echo $r['created_at']; ?></td></tr><?php } ?></table></div></div></div><?php include '../includes/footer.php'; ?>
